package enum Assumption: String, CaseIterable, Sendable {
    case applicationLifecycle = "application-lifecycle"
    case applicationActivation = "application-activation"
    case applicationVisibility = "application-visibility"
    case axApplicationWindows = "ax-application-windows"
    case axWindowAttributes = "ax-window-attributes"
    case axSizeConstraints = "ax-size-constraints"
    case axFocus = "ax-focus"
    case axNotifications = "ax-notifications"
    case axSubscriptions = "ax-subscriptions"
    case axMessagingTimeout = "ax-messaging-timeout"
    case axReadDelivery = "ax-read-delivery"
    case transientWindowLists = "transient-window-lists"
    case closedWindowHandles = "closed-window-handles"
    case staleChromeDescendant = "stale-chrome-descendant"
    case minimizeRestore = "minimize-restore"
    case nativeFullscreen = "native-fullscreen"
    case nativeTabIdentity = "native-tab-identity"
    case windowGeometryWrites = "window-geometry-writes"
    case cgOnScreenOrder = "cg-on-screen-order"
    case windowServerListing = "window-server-listing"
    case windowLevels = "window-levels"
    case primaryScreenGeometry = "primary-screen-geometry"
    case closetMoves = "closet-moves"
    case closetMembership = "closet-membership"
    case finderDesktop = "finder-desktop"
    // #1 scenarios
    case backgroundWindowCreation = "background-window-creation"
    case contentTabChrome = "content-tab-chrome"
    case nativeTabExtraControls = "native-tab-extra-controls"
    case delayedNativeTabFocus = "delayed-native-tab-focus"
    // #2 scenarios
    case activationHiddenFocus = "activation-hidden-focus"
    case closeFocusPromotion = "close-focus-promotion"
    case sheetFocusOwnership = "sheet-focus-ownership"
    case nativeTabInsertion = "native-tab-insertion"
    // #17 scenarios
    case sizeLimitChanges = "size-limit-changes"
    case terminationActivationOrder = "termination-activation-order"
    case nativeTabPublication = "native-tab-publication"
    case deferredAXActivation = "deferred-ax-activation"
    case activationKeyRestoration = "activation-key-restoration"
    case minimizeFocusInterruption = "minimize-focus-interruption"
    case axFrontmostActivation = "ax-frontmost-activation"

    case axVerticalClamping = "ax-vertical-clamping"
    case axHorizontalSliver = "ax-horizontal-sliver"
    case axRaiseAcrossApplications = "ax-raise-across-applications"
    case closetAXIdentity = "closet-ax-identity"
    case closetSizeLoss = "closet-size-loss"
    case enhancedUIResize = "enhanced-ui-resize"
    case screenRecordingPreflight = "screen-recording-preflight"
    case stageWholeWindowCapture = "stage-whole-window-capture"
    case stageProtectedCapture = "stage-protected-capture"
    case stageOverlay = "stage-overlay"
    case reduceMotionNotifications = "reduce-motion-notifications"
    case pointerPressNotifications = "pointer-press-notifications"
    case axResizeAnchoring = "ax-resize-anchoring"

    package var statement: String {
        switch self {
        case .enhancedUIResize: "With AXEnhancedUserInterface enabled, a size followed by position loses the size; disabling it around the write and restoring it preserves the requested geometry. AppKit may apply the flag while returning notImplemented."
        case .axResizeAnchoring: "AXSize can be constrained by the current positive x and by the current top against the screen bottom; moving first allows the requested size."
        case .pointerPressNotifications: "An NSEvent global monitor receives another app's mouse press before drag events and its release after them."
        case .axVerticalClamping: "AXPosition keeps the top below the menu bar and at least 32 points visible at the screen bottom."
        case .axHorizontalSliver: "AXPosition accepts a one-point horizontal sliver, but a wholly off-screen window snaps back to show 40 points."
        case .axRaiseAcrossApplications: "AXMain selects a background app's card without activation, then AXRaise reorders it; a frontmost app window may remain above a raised background window, and closet return preserves earlier order."
        case .closetAXIdentity: "A retained AX element survives a closet round trip and accepts position writes while closeted."
        case .closetSizeLoss: "An AXSize write while closeted may return a shorter height after the window is shown."
        case .screenRecordingPreflight: "CGPreflightScreenCaptureAccess reports the Screen Recording grant without prompting; CGRequestScreenCaptureAccess asks once."
        case .stageWholeWindowCapture: "With Screen Recording, ScreenCaptureKit captures a whole window at its live size, including a window in the closet or partly off screen, serially, without moving or activating it. Off screen, only a window in the closet, with no ordinary Space, is drawn; a hidden or ordering-out window keeps its ordinary Space."
        case .stageProtectedCapture: "A BGRA window screenshot containing capture-protected video has an IOSurface that locks successfully but has no base address. A display screenshot including that window is readable, and removing capture protection makes the window screenshot readable again."
        case .stageOverlay: "A borderless, click-through window at floating level is listed above tiled windows and below the menu bar within one display frame of its commit, without taking focus or receiving the pointer; WindowServer may draw it tens of milliseconds later, which its owner can read from its own window without Screen Recording."
        case .reduceMotionNotifications: "NSWorkspace exposes Reduce Motion and posts accessibilityDisplayOptionsDidChangeNotification when it changes."
        case .applicationLifecycle: "Application metadata describes activation policy and liveness; regular apps notify launch and termination, while prohibited apps may omit either notification."
        case .applicationActivation: "Plain activation changes the frontmost app without ordering all its windows, and notification delivery may lag."
        case .applicationVisibility: "App hide changes AXHidden and CG visibility, while AXWindows may omit hidden windows."
        case .axApplicationWindows: "AXWindows lists ordinary roots in app order, including minimized windows but excluding attached sheets."
        case .axWindowAttributes: "AX publishes subrole, frame, children and size settability; ordinary windows expose minimized/fullscreen flags while attached sheets report attributeUnsupported."
        case .axSizeConstraints: "An AXSize write may succeed with a size clamped to the window's minimum and maximum."
        case .axFocus: "AXFocusedWindow identifies key focus and AXMain the main root; sheets report attributeUnsupported for AXMain, and making a root main or raising it may select it."
        case .axNotifications: "AX notifications arrive on the main lane after the native operation, with focus/main notification order allowed to vary."
        case .axSubscriptions: "Observers register per-element notifications, retain equal element identity, and stop delivering after removal."
        case .axMessagingTimeout: "Timeout configuration is client-side and succeeds while the target app is stopped; remote AX calls to a hung app fail with cannotComplete after the handle's messaging timeout."
        case .axReadDelivery: "An AX reply describes state captured by that call, even when delivery happens later."
        case .transientWindowLists: "AXWindows may omit handles, expose zero IDs, fail or change during transitions, including a temporary nonresizable display-sized AXUnknown root with AXFullScreen false and creation/destruction notifications during native fullscreen."
        case .closedWindowHandles: "On macOS 27, a closed AppKit window's retained AX handle returns illegalArgument with CG ID 0, while attribute reads return invalidUIElement, even when the NSWindow is retained."
        case .staleChromeDescendant: "Removing a subview invalidates its cached AX element while its replacement and the window root remain valid, with the same window ID."
        case .minimizeRestore: "Minimize and restore change AX and CG state, with notifications after the Dock operation and a selectable successor."
        case .nativeFullscreen: "A native fullscreen window occupies a separate Space and leaves ordinary desktop visibility until exit; entry emits AXWindowResized."
        case .nativeTabIdentity: "Native tabs share a frame and retain their AX bar identity across selected roots, while minimized tabs are listed separately."
        case .windowGeometryWrites: "AX position and size writes are independent and emit AXWindowMoved and AXWindowResized; a successful position write may accept the requested point or clamp it at the display's right edge to leave a 40-point visible strip."
        case .cgOnScreenOrder: "CG lists active-Space windows front to back, excluding hidden and minimized windows; a window entirely outside the display may remain listed."
        case .windowServerListing: "WindowServer lists the last app-committed frame, separately from AX acceptance, including in the closet. Geometry commits lag AX replies and wait while the app is stopped or busy; a closet hide lists the window off screen."
        case .windowLevels: "CG reports each window's layer by ID, including off-Space windows in the closet; ordinary and dialog windows are at layer 0, an NSPanel with isFloatingPanel at its default level is an AXFloatingWindow at layer 3, a borderless child popup is an AXUnknown root at layer 0, and a status-bar-level window has a layer other than 0 or 3."
        case .primaryScreenGeometry: "The primary screen exposes full and visible frames in bottom-origin coordinates while AX uses top-origin coordinates."
        case .closetMoves: "SkyLight moves windows and their sheets between the active Space and an invisible closet without changing native focus."
        case .closetMembership: "Ordinary Space queries omit closets; all-Space queries may retain closet membership alongside the active Space after showing a window, until the closet is destroyed."
        case .finderDesktop: "Finder exposes its desktop as an AXScrollArea without a window ID or subrole and can activate it without reopening windows."
        // #1 scenarios
        case .backgroundWindowCreation: "Opening a window in the background posts a creation notification without changing app focus or main window."
        case .contentTabChrome: "Content tabs expose childless buttons separately from flattened selected-page contents: empty pages publish no content, populated pages publish AXStaticText in AXContents and AXChildren, and segmented radio groups expose only child buttons with unsupported tabs/contents attributes."
        case .nativeTabExtraControls: "A native tab bar's AXContents may include a New Tab button beyond AXTabs, and native tabs need not have close buttons."
        case .delayedNativeTabFocus: "AXWindows may retain the former native-tab root after its bar moves while AXFocusedWindow is unavailable until the selected root is published."
        // #2 scenarios
        case .activationHiddenFocus: "Plain activation can leave an app's focused window in the closet, with AX focus still readable, and unhides a hidden app."
        case .closeFocusPromotion: "Closing a key window can promote a closeted sibling before the destruction notification is delivered."
        case .sheetFocusOwnership: "An attached sheet keeps key focus when its parent is raised or made main, while the parent owns AXMain."
        case .nativeTabInsertion: "Adding a native tab preserves bar identity and shared frame while selecting the new front; its new root belongs to the active desktop and may become CG-visible even when inserted into a closeted background group."
        // #17 scenarios
        case .sizeLimitChanges: "Changing an AppKit window's maximum size leaves its current frame intact and clamps the next size write."
        case .terminationActivationOrder: "A dying process may still satisfy a liveness probe when macOS activates a survivor before termination notification delivery; window destruction, process exit and lifecycle delivery are separate."
        case .nativeTabPublication: "A native tab's bar can identify its successor while AXWindows still lists the former root and AXFocusedWindow is temporarily unpublished."
        case .deferredAXActivation: "AX can accept activation before the app becomes active; pending activation may complete asynchronously, on a main or raise write, or on another activation request."
        case .activationKeyRestoration: "An AX activation can finish after the AXMain and AXRaise that follow it; when the selected window is in the closet, the app's previous key window becomes key again, and AXMain and AXRaise after the activation select the requested window."
        case .minimizeFocusInterruption: "AX main or raise can cancel pending minimization; after completion main leaves it minimized, while raise restores it and may return cannotComplete before the restore finishes."
        case .axFrontmostActivation: "AXFrontmost activation orders every window of the app above other apps' windows."
        }
    }
}
